def _key(q: str) -> str:
    """مفتاح التكرار: يوحّد التشكيل والهمزات والتاء المربوطة (عَبين = عبين، صخره = صخرة) ويُبقي علامة الاقتباس (عبارة حرفية ≠ بحث عادي)."""
    return normalize(q) + ("|exact" if '"' in q else "")


def extended(existing: list[str]) -> list[str]:
    """الاستعلامات الموسّعة بلا تكرار فيما بينها ولا مع الاستعلامات الأساسية."""
    seen = {_key(q) for q in existing}
    out: list[str] = []
    for line in RAW.strip().splitlines():
        for q in line.split("|"):
            q = q.strip()
            k = _key(q)
            if q and k not in seen:
                seen.add(k)
                out.append(q)
    return out
